Gamma0.Transforms≡:
{m = n : ℕ} {n = m : ℕ}
{A = d : Coefficient.Mat ℤCommRing n m}
{D = M : Coefficient.Mat ℤCommRing n m}
{s = i : Transforms d M} {t = j : Transforms d M} →
i .fst ≡ j .fst → i ≡ j

Gamma0.compT:
{m = n : ℕ} {n = m : ℕ}
{A = d : Coefficient.Mat ℤCommRing n m}
{B = M : Coefficient.Mat ℤCommRing n m}
{C = i : Coefficient.Mat ℤCommRing n m} →
Transforms d M → Transforms M i → Transforms d i

Gamma0.invT:
{m = n : ℕ} {n = m : ℕ}
{A = d : Coefficient.Mat ℤCommRing n m}
{D = M : Coefficient.Mat ℤCommRing n m} →
Transforms d M → Transforms M d

Gamma0.act:
{m = n : ℕ} {n = m : ℕ}
{A = d : Coefficient.Mat ℤCommRing n m}
{D = M : Coefficient.Mat ℤCommRing n m} →
Stab M → Transforms d M → Transforms d M

Gamma0.act-transitive:
{m = n : ℕ} {n = m : ℕ}
{A = d : Coefficient.Mat ℤCommRing n m}
{D = M : Coefficient.Mat ℤCommRing n m}
(i j : Transforms d M) →
Σ-syntax (Stab M) (λ s → act s i ≡ j)

Gamma0.act-free:
{m = n : ℕ} {n = m : ℕ}
{A = d : Coefficient.Mat ℤCommRing n m}
{D = M : Coefficient.Mat ℤCommRing n m}
(i : Transforms d M) (j : Stab M) →
act j i ≡ i → j ≡ idT M

